pub fn SIInterruptHandler<'a>(ctx: &'a Ctx, a0: i16, a1: OSContext<'a>) {
    // Transliterated from its machine code: hardware register order.
    (a0, a1).put_regs(ctx);
    asm_SIInterruptHandler(ctx);
}

