pub fn SIRegisterPollingHandler<'a>(ctx: &'a Ctx, handler: FnPtr<'a>) -> i32 {
    let __frame = ctx.stack_frame(0x18);
    let mut handler = handler;
    let mut enabled: i32 = 0;
    let mut i: i32 = 0;
    enabled = fns::OSDisableInterrupts(ctx);
    {
        i = 0_i32;
        'l1: while i < 4_i32 {
            'c2: {
                if Handle::addr(statics::dolphin__os__OSSerial::RDSTHandler(ctx).at(i).get())
                    == Handle::addr(handler)
                {
                    let _ = fns::OSRestoreInterrupts(ctx, enabled);
                    return 1_i32;
                }
            }
            i = i.wrapping_add(1);
        }
    }
    {
        i = 0_i32;
        'l3: while i < 4_i32 {
            'c4: {
                if Handle::is_null(statics::dolphin__os__OSSerial::RDSTHandler(ctx).at(i).get()) {
                    statics::dolphin__os__OSSerial::RDSTHandler(ctx)
                        .at(i)
                        .set(handler);
                    let _ = statics::dolphin__os__OSSerial::SIEnablePollingInterrupt(ctx, 1_i32);
                    let _ = fns::OSRestoreInterrupts(ctx, enabled);
                    return 1_i32;
                }
            }
            i = i.wrapping_add(1);
        }
    }
    let _ = fns::OSRestoreInterrupts(ctx, enabled);
    return 0_i32;
}

pub fn SIUnregisterPollingHandler<'a>(ctx: &'a Ctx, handler: FnPtr<'a>) -> i32 {
    let __frame = ctx.stack_frame(0x18);
    let mut handler = handler;
    let mut enabled: i32 = 0;
    let mut i: i32 = 0;
    enabled = fns::OSDisableInterrupts(ctx);
    {
        i = 0_i32;
        'l1: while i < 4_i32 {
            'c2: {
                if Handle::addr(statics::dolphin__os__OSSerial::RDSTHandler(ctx).at(i).get())
                    == Handle::addr(handler)
                {
                    statics::dolphin__os__OSSerial::RDSTHandler(ctx)
                        .at(i)
                        .set(null::<FnPtr<'a>>(ctx));
                    {
                        i = 0_i32;
                        'l3: while i < 4_i32 {
                            'c4: {
                                if !Handle::is_null(
                                    statics::dolphin__os__OSSerial::RDSTHandler(ctx).at(i).get(),
                                ) {
                                    break 'l3;
                                }
                            }
                            i = i.wrapping_add(1);
                        }
                    }
                    if i == 4_i32 {
                        let _ =
                            statics::dolphin__os__OSSerial::SIEnablePollingInterrupt(ctx, 0_i32);
                    }
                    let _ = fns::OSRestoreInterrupts(ctx, enabled);
                    return 1_i32;
                }
            }
            i = i.wrapping_add(1);
        }
    }
    let _ = fns::OSRestoreInterrupts(ctx, enabled);
    return 0_i32;
}

